// Run against the production bundle generated by npm run package.
// This test uses a separate profile and disables network, clipboard capture,
// login settings and global shortcuts so it cannot change the user's setup.
if (!process.versions.electron) {
  const env = { ...process.env };
  delete env.NODE_OPTIONS;
  delete env.ELECTRON_RUN_AS_NODE;
  const result = require("child_process").spawnSync(
    require("electron"),
    [__filename],
    {
      env,
      stdio: "inherit",
    },
  );
  if (result.error) throw result.error;
  process.exit(result.status ?? 1);
}

const { app, BrowserWindow, session, globalShortcut } = require("electron");
const fs = require("fs");
const path = require("path");
const assert = require("assert/strict");
const root = path.resolve(__dirname, "..");
const outputDirectory = path.join(root, "out");
fs.mkdirSync(outputDirectory, { recursive: true });
const fixture = fs.mkdtempSync(path.join(outputDirectory, "startup-fixture-"));
const started = performance.now();
app.setPath("userData", fixture);
app.setAppPath(root);
Object.defineProperty(app, "isPackaged", { get: () => true });
// Test fixtures must not change Windows startup settings or register real shortcuts.
app.setLoginItemSettings = () => {};
globalShortcut.register = () => true;
globalShortcut.unregister = () => {};
globalShortcut.unregisterAll = () => {};
process.argv.push("--autostart");
fs.writeFileSync(
  path.join(fixture, "settings.json"),
  JSON.stringify({
    "launch-on-startup": "true",
    "close-to-tray": "true",
    "update-preference": "false",
    clipboardRecommendationsEnabled: "false",
    voiceTranscriptionEnabled: "false",
  }),
);
fs.mkdirSync(path.join(fixture, "clipboard-history"));
fs.writeFileSync(
  path.join(fixture, "clipboard-history/history.dat"),
  JSON.stringify({
    items: [],
    rules: [],
    settings: { enabled: false, shortcutEnabled: false },
  }),
);
let main;
const errors = [];
app.on("browser-window-created", (_event, window) => {
  if (main) return;
  main = window;
  main.webContents.on("console-message", (_e, level, message) => {
    if (level === 3 && /Uncaught|ChunkLoadError|Loading chunk/.test(message))
      errors.push(message);
  });
  main.webContents.on("render-process-gone", (_e, details) =>
    errors.push(details.reason),
  );
});
app.whenReady().then(() => {
  session.defaultSession.webRequest.onBeforeRequest(
    { urls: ["http://*/*", "https://*/*"] },
    (_details, callback) => callback({ cancel: true }),
  );
});
require(path.join(root, ".webpack/main/index.js"));
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
async function until(probe, timeout = 20000) {
  const deadline = performance.now() + timeout;
  while (performance.now() < deadline) {
    if (await probe()) return;
    await delay(30);
  }
  throw new Error("Timed out waiting for renderer");
}
(async () => {
  await app.whenReady();
  await until(
    async () =>
      main &&
      !main.webContents.isLoading() &&
      (await main.webContents.executeJavaScript(
        'document.querySelectorAll("main a[href]").length > 40',
      )),
  );
  const startupMs = Math.round(performance.now() - started);
  // Capture the clean fixture, never the user's profile or clipboard.
  const homeScreenshot = await main.webContents.capturePage();
  fs.writeFileSync(path.join(outputDirectory, 'open-source-home.png'), homeScreenshot.toPNG());
  assert.equal(
    main.isVisible(),
    false,
    "Autostart should preload while hidden",
  );
  const originalId = main.id;
  const contentBefore = await main.webContents.executeJavaScript(
    'document.querySelector("main").textContent',
  );
  const revealed = performance.now();
  app.emit("second-instance");
  await until(() => main.isVisible());
  const revealMs = Math.round(performance.now() - revealed);
  assert.equal(main.id, originalId);
  main.close();
  assert.equal(main.isDestroyed(), false);
  await until(() => !main.isVisible());
  app.emit("second-instance");
  await until(() => main.isVisible());
  assert.equal(
    await main.webContents.executeJavaScript(
      'document.querySelector("main").textContent',
    ),
    contentBefore,
  );
  main.minimize();
  await until(() => main.isMinimized());
  app.emit("second-instance");
  await until(() => !main.isMinimized());
  assert.equal(BrowserWindow.getAllWindows().length, 1);
  const routes = [
    "/json-format",
    "/excel-converter",
    "/image-optimizer",
    "/markdown-preview",
    "/js-obfuscator",
    "/json-schema-validator",
    "/typescript-to-js",
    "/clipboard-history",
    "/screenshot-studio",
    "/screen-recorder",
    "/video-editor",
    "/capture-library",
    "/",
  ];
  const visited = [];
  for (const route of routes) {
    console.log('SMOKE_ROUTE ' + route);
    const previousMarkup = await main.webContents.executeJavaScript(
      'document.querySelector("main").innerHTML',
    );
    await main.webContents.executeJavaScript(
      `location.hash = ${JSON.stringify("#" + route)}`,
    );
    await until(
      async () =>
        await main.webContents.executeJavaScript(
          `location.hash === ${JSON.stringify("#" + route)} && document.querySelector('main')?.innerHTML !== ${JSON.stringify(previousMarkup)} && document.querySelector('main')?.textContent.trim().length > 30 && !Array.from(document.querySelectorAll('main [role="status"]')).some(element => element.textContent.trim() === 'Loading tool…')`,
        ),
    );
    await delay(80);
    assert.equal(errors.length, 0, errors.join("\n"));
    visited.push(route);
  }
  assert.equal(main.id, originalId);
  console.log(
    "STARTUP_SMOKE_RESULT " +
      JSON.stringify({ startupMs, revealMs, visited, errors }),
  );
  app.exit(0);
})().catch((error) => {
  console.error(error);
  app.exit(1);
});
setTimeout(() => {
  console.error("Smoke test deadline");
  app.exit(1);
}, 90000);
